/* ============================
   Lumexa Portfolio Website — starter styles
   Replace --brand / --brand-dark / --accent in Lesson 5 with your own brand colors.
   ============================ */

:root {
  --brand: #2f6fed;
  --brand-dark: #1c4fc4;
  --accent: #ffcb47;
  --ink: #16192b;
  --sub: #5a5f75;
  --bg: #ffffff;
  --bg-alt: #f5f7fb;
  --line: #e4e7f0;
  --radius: 14px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: 'Segoe UI', Arial, sans-serif;
  color: var(--ink);
  background: var(--bg);
  line-height: 1.6;
}

a { color: var(--brand); }

.hero {
  background: linear-gradient(135deg, var(--brand), var(--brand-dark));
  color: white;
  padding: 64px 20px 48px;
  text-align: center;
}
.hero-inner { max-width: 720px; margin: 0 auto; }
.eyebrow {
  text-transform: uppercase;
  letter-spacing: 2px;
  font-size: 12px;
  font-weight: 700;
  opacity: 0.85;
  margin: 0 0 8px;
}
.hero h1 { font-size: 40px; margin: 0 0 12px; }
.tagline { font-size: 17px; opacity: 0.95; margin: 0 0 24px; }
.hero-nav a {
  color: white;
  text-decoration: none;
  margin: 0 12px;
  font-weight: 600;
  border-bottom: 2px solid transparent;
  padding-bottom: 4px;
}
.hero-nav a:hover { border-bottom-color: var(--accent); }

main { max-width: 880px; margin: 0 auto; }

.section { padding: 56px 24px; }
.section.alt { background: var(--bg-alt); }
.section h2 {
  font-size: 26px;
  margin: 0 0 20px;
  border-left: 5px solid var(--brand);
  padding-left: 12px;
}

.placeholder { color: var(--sub); font-style: italic; }

.skills-grid {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 0;
  margin: 0;
}
.skills-grid li {
  background: white;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 18px;
  font-weight: 600;
  font-size: 14px;
}

.projects-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
}
.project-card {
  background: white;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px;
}
.project-card h3 { margin: 0 0 8px; font-size: 18px; }
.project-link { font-weight: 700; text-decoration: none; font-size: 14px; }

.note { font-size: 13px; color: var(--sub); }

.footer {
  text-align: center;
  padding: 28px 20px;
  color: var(--sub);
  font-size: 13px;
  border-top: 1px solid var(--line);
}

/* Responsive */
@media (max-width: 480px) {
  .hero h1 { font-size: 30px; }
  .hero-nav a { display: inline-block; margin: 4px 8px; }
}
